import axios from "axios";
import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";


function Community() {
    const {id} = useParams();
    const [posts, setPosts] = useState([]);
     const fetchPosts = async () => {
            try {
                const resp = await axios.get(`http://10.124.215.133:8000/api/posts/?community=${id}&limit=5`, {
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
                });
                const postsResp = resp.data.results || resp.data;
                if (postsResp.length > 0) {
                    setPosts(postsResp);
                    console.log(posts);
                }
            } catch (err) {
                console.error("Err loading post", err);
            }
        };
    useEffect(()=>{
        fetchPosts();
    }, [])
    return (posts.map(post=>(<div>
        <div>{post.author}</div>
        <div>{post.text}</div>
    </div>)));
}

export default Community;
